{
  "name": "builder_all_pairs_margin_rank_blend_tiezone",
  "intuition": "Preserves margin_rank_blend weighting with explicit tie-zone filtering to zero small margin pairs, stabilizing weights",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "margin_rank_blend",
    "constraint_family": "tiezone_filtered"
  },
  "operators_used": [
    "all_pairs",
    "margin_rank_blend",
    "tiezone_filter",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "rank"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    rank = feature_cache['rank']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'margin_rank_blend'})\n    eps = 1e-6\n    beta_rank = float(extra.get('beta_rank', 4.0))\n    gamma = float(extra.get('gamma', 0.5))\n    margin_abs = (log_prob[b_idx, winner_idx] - log_prob[b_idx, loser_idx]).abs()\n    rank_span = rank[b_idx, loser_idx] - rank[b_idx, winner_idx]\n    raw = torch.sigmoid(beta_rank * rank_span) / (margin_abs + eps).pow(gamma)\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)\n    tiezone = float(extra.get('tiezone', 0.1))\n    # Zero weights where margin_abs is less than tiezone threshold\n    raw = raw * (margin_abs > tiezone).float()\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'margin_rank_blend'})\n"
}

{
  "name": "builder_all_pairs_gap_bandpass_v2",
  "intuition": "reweight all pairs using a bandpass filter on the cost gap emphasizing medium gaps with smooth decay",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_bandpass_v2",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "gap_bandpass"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "obj_z",
      "rank",
      "regret"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass_v2'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Parameters for bandpass: center and width from extra or defaults\n    center = float(extra.get('center', 1.0))\n    width = float(extra.get('width', 0.5))\n    eps = 1e-6\n    # Compute bandpass weight as a smooth triangle shape around center gap\n    dist = (gap - center).abs()\n    raw = (width - dist).clamp(min=0.0) / (width + eps)\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp(min=0.0)\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass_v2'})\n"
}

