{
  "name": "builder_all_pairs_gap_bandpass_010",
  "intuition": "reweight all pairs using a bandpass filter on gap magnitude to emphasize medium gaps",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_bandpass",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "gap_bandpass"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_abs = gap.abs()\n    low = float(extra.get('low', 0.1))\n    high = float(extra.get('high', 1.0))\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    # bandpass weighting: emphasize gaps between low and high\n    weight = ((gap_abs - low) * (high - gap_abs)).clamp(min=0.0)\n    weight = torch.nan_to_num(weight, nan=0.0, posinf=0.0, neginf=0.0).clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass'})\n"
}

