{
  "name": "all_pairs_gap_linear_clamp_001_fixed",
  "intuition": "Construct all pairs where objective_a < objective_b, weighting pairs by the positive gap clipped within configurable bounds, preserving the original gap_linear weighting without rescaling or normalization.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # mask for pairs where obj_a < obj_b\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # if no pairs, return empty PrefBatch with zero weights\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear', 'constraint_family': 'clamp_only'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]  # positive gap\n    # clamp gap linearly to [clamp_lo, clamp_hi], default 0.1 to 3.0\n    clamp_lo = float(extra.get('clamp_lo', 0.1))\n    clamp_hi = float(extra.get('clamp_hi', 3.0))\n    weight = gap.clamp(min=clamp_lo, max=clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear', 'constraint_family': 'clamp_only'})"
}
