{
  "name": "all_pairs_gap_linear_reweight_fixed",
  "intuition": "Preserves the fixed all-pairs pair structure exactly as in the fixed template and reweights pairs by a nonnegative linear function of the positive objective gap, ensuring stable weights reflecting preference strength without altering pair topology.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Construct all pairs as in the fixed all_pairs builder: winner objective > loser objective\n    mask = objective[:, :, None] > objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # Compute positive gap as difference winner - loser\n    gap = objective[b_idx, winner_idx] - objective[b_idx, loser_idx]\n    # Compute linear weights with configurable scale and offset (clamped at zero to ensure nonnegativity)\n    weight_scale = float(extra.get('weight_scale', 1.0))\n    weight_offset = float(extra.get('weight_offset', 0.0))\n    raw_weight = weight_scale * gap + weight_offset\n    raw_weight = raw_weight.clamp_min(0.0)\n    # Return PrefBatch with fixed pair_idx and new weights\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=raw_weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})"
}
