{
  "name": "all_pairs_gap_exp_clamp_002",
  "intuition": "All-pairs topology with pair weights as a clamped exponential decay of the objective gap, computed fully vectorized without imports and preserving pairwise mask and indexing.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "rank"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Construct pairwise mask where objective[i,j] < objective[i,k]\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # If no pairs, return empty PrefBatch with no weight\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_exp_clamp'})\n    # Compute gap = objective_loser - objective_winner\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    beta = float(extra.get('beta', 1.0))\n    # weight = exp(-beta * gap), clamp to [0.25, 4.0]\n    raw = (-(beta * gap)).exp()\n    raw = raw.clamp(0.25, 4.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=raw, meta={'builder': 'all_pairs', 'weight_family': 'gap_exp_clamp'})"
}
