{
  "name": "builder_all_pairs_margin_regret_blend_clamp_rescale_005",
  "intuition": "Refined margin_regret_blend weights by adding configurable rescaling and tighter clamping for improved stability in all_pairs topology",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "margin_regret_blend",
