  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob",
      "obj_z",
      "rank",
      "regret"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'margin_regret_blend'})\n    eps = 1e-6\n    regret = feature_cache['regret']\n    lambda_regret = float(extra.get('lambda_regret', 1.0))\n    gamma = float(extra.get('gamma', 0.5))\n    clamp_lo = float(extra.get('clamp_lo', 0.5))\n    clamp_hi = float(extra.get('clamp_hi', 2.0))\n    rescale = float(extra.get('rescale', 1.0))\n    margin_abs = (log_prob[b_idx, winner_idx] - log_prob[b_idx, loser_idx]).abs()\n    regret_span = regret[b_idx, loser_idx] - regret[b_idx, winner_idx]\n    raw = (1.0 + lambda_regret * regret_span) / (margin_abs + eps).pow(gamma)\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)\n    weight = (raw * rescale).clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'margin_regret_blend'})\n"
}

