  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass_smooth_clip'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    low = float(extra.get('bandpass_low', 0.1))\n    high = float(extra.get('bandpass_high', 1.0))\n    softness = float(extra.get('bandpass_softness', 0.1))\n    clamp_lo = float(extra.get('clamp_lo', 0.1))\n    clamp_hi = float(extra.get('clamp_hi', 3.0))\n    # smooth bandpass weighting: positive in (low, high), decays exponentially outside\n    inside = (gap - low) * (high - gap)\n    inside = inside.clamp(min=0.0)\n    below = torch.exp(-(low - gap) / softness) * (gap < low).float()\n    above = torch.exp(-(gap - high) / softness) * (gap > high).float()\n    raw = inside + below + above\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=0.0, neginf=0.0).clamp_min(0.0)\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass_smooth_clip'})"
